<?php require '_init.php';$pageTitle='Change admin password';$errors=[];if(post()){verify_csrf();$a=query('SELECT * FROM admins WHERE id=?',[$currentAdmin['id']])->fetch();$password=textval('password');$errors=password_errors($password);if(!password_verify(textval('current_password'),$a['password']))$errors[]='Current password is incorrect.';if($password!==textval('confirm_password'))$errors[]='New passwords do not match.';if(password_verify($password,$a['password']))$errors[]='Choose a different password.';if(!$errors){query('UPDATE admins SET password=?,must_change_password=0 WHERE id=?',[password_hash($password,PASSWORD_BCRYPT),$a['id']]);session_regenerate_id(true);flash('Admin password changed.');redirect('admin/index.php');}}require '../includes/header.php';?><section class="container section"><div class="panel auth-panel"><h1>Change password</h1><p>Replace your temporary password before managing the store.</p><?php errors($errors);?><form method="post" data-validate><?php csrf();?><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="72" required></label><label>Confirm new password<input type="password" name="confirm_password" autocomplete="new-password" minlength="10" maxlength="72" required></label><button>Save password</button></form></div></section><?php require '../includes/footer.php';?>
